unsafe fn Mask_calcN2(
    mut width: c_int,
    mut frame: *mut c_uchar,
) -> c_int {
    let mut demerit: c_int = 0;
    if width <= 1 {
        return demerit;
    }

    let w = width as isize;
    let mut y: c_int = 1;
    let mut row = frame.offset(w).offset(1);

    while y < width {
        let mut x: c_int = 1;
        let mut p = row;
        while x < width {
            let c = *p as c_int;
            let l = *p.offset(-1) as c_int;
            let u = *p.offset(-w) as c_int;
            let ul = *p.offset(-w - 1) as c_int;

            if ((c & l & u & ul) | ((c | l | u | ul) ^ 1)) & 1 != 0 {
                demerit += N2;
            }

            p = p.offset(1);
            x += 1;
        }
        row = row.offset(w + 1);
        y += 1;
    }

    demerit
}

